-- 1. SEED STRATEGY CATEGORIES (10 DOMAINS)
INSERT INTO strategy_categories (category_id, domain_name, description) VALUES
('DOM_01', 'Drainage & Stormwater', 'Engineering and physical measures to manage urban surface runoff, primary channels, and stormwater storage.'),
('DOM_02', 'Water Management', 'Groundwater recharge, traditional Eri lake rejuvenation, rainwater harvesting, and water conservation.'),
('DOM_03', 'Urbanization & Land Use', 'Spatial planning, floodplain zoning, setback enforcement, and blue-green infrastructure land allocation.'),
('DOM_04', 'Green / Nature-Based Solutions', 'Bioswales, permeable pavements, urban eco-restoration, and natural retention systems.'),
('DOM_05', 'Built Infrastructure', 'Physical infrastructure retrofits, raised plinths, power asset flood-proofing, and resilient cross-sections.'),
('DOM_06', 'Terrain / GIS / Geometry', 'DEM-guided micro-catchment modeling, slope-based runoff interception, and spatial elevation planning.'),
('DOM_07', 'Critical Infrastructure', 'Hospitals, emergency relief shelters, back-up power elevation, and water supply protection.'),
('DOM_08', 'Early Warning & Preparedness', 'IoT river gauges, hydro-meteorological sensors, telemetry platforms, and evacuation early warning systems.'),
('DOM_09', 'Heat Resilience', 'Cool roofs, high-albedo coatings, shade tree canopy expansion, and thermal comfort retrofits.'),
('DOM_10', 'Coastal / Marine Adaptation', 'Mangrove bio-shields, tidal mudflat restoration, and submerged artificial breakwater reefs.')
ON CONFLICT (category_id) DO NOTHING;

